{
  "name": "@northwiser/opencode-prodigo",
  "version": "0.1.0-beta.1",
  "description": "Prodigo for OpenCode, by Northwiser LLC: Pega onboarding and rule fetching through Prodigo Core.",
  "author": {
    "name": "Northwiser LLC",
    "email": "info@northwiser.ai"
  },
  "bugs": {
    "email": "info@prodigo.ai"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "prodigo",
    "northwiser",
    "pega"
  ],
  "type": "module",
  "license": "MIT",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./rpc": {
      "types": "./dist/rpc.d.ts",
      "import": "./dist/rpc.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "SECURITY.md",
    "CHANGELOG.md",
    "THIRD_PARTY_NOTICES.md",
    "config.example.jsonc"
  ],
  "dependencies": {
    "@opencode/plugin": "2.2.7"
  },
  "engines": {
    "node": ">=22.19.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jgasmi/pega-local-router.git",
    "directory": "plugins/prodigo"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
