}

import { createHash, randomUUID } from "node:crypto";
import { Plugin } from "@opencode/plugin";
import { DEFAULTS, loadConfig } from "./config.js";
import { CoreError, createCoreClient, describeRunEvent } from "./core.js";
import { applyTarget } from "./mcp.js";
import { ensureWritableFolder, normalizeOutputFolder, OutputFolderError, suggestOutputFolder } from "./output.js";
import { createPortal } from "./portal.js";
import { ALL_RULE_TYPE_IDS } from "./rule-types.js";
import { ProdigoRpc } from "./rpc.js";
import { createStore } from "./store.js";
import { coreServiceBaseUrl, createCoreTrust, CoreTrustError, sameTarget } from "./trust.js";
export default Plugin.define({
    id: "prodigo",
    async setup(ctx) {
        const directory = ctx.location?.directory ?? process.cwd();
        const config = loadConfig(ctx.options, directory);
        const store = createStore(config.state.directory);
        const portal = createPortal(config);
        const trust = createCoreTrust();
        const core = createCoreClient();
        // The MCP transform callback is synchronous, so the live selection is held
        // in memory and hydrated from disk at setup. Persistence is best-effort.
        const hydrated = await store.read("state").catch(() => undefined);
        let target = hydrated?.target;
        let pegaConnection = hydrated?.pega?.ready && target && sameTarget(target.baseUrl, hydrated.pega.targetBaseUrl) ? hydrated.pega.connectionName : undefined;
        let mcpUrl;
        let mcpInfo = { configured: false, patched: false };
        let activeRun;
        let savedOutput = (await store.read("settings").catch(() => undefined))?.outputRoot;
        if (config.report)
            console.log(`[opencode-prodigo] loaded (portal=${config.portal.baseUrl}, mcp server=${config.mcp.server})`);
        async function currentToken() {
            if (config.tokenEnv) {
                const value = process.env[config.tokenEnv]?.trim();
                if (value)
                    return { token: value, source: "environment" };
            }
            const credentials = await store.read("credentials").catch(() => undefined);
            if (credentials?.token)
                return { token: credentials.token, source: "store" };
            return { source: "none" };
        }
        function readState() {
            return store.read("state").catch(() => ({})).then((value) => value ?? {});
        }
        // All state mutations go through one queue so concurrent RPCs cannot lose updates.
        let stateQueue = Promise.resolve();
        function updateState(mutate) {
            const next = stateQueue.then(async () => {
                const state = await readState();
                await store.write("state", mutate(state)).catch(() => undefined);
            });
            stateQueue = next.catch(() => undefined);
            return next;
        }
        const registrations = [];
        registrations.push(await ctx.mcp.transform((editor) => {
            const editorLike = editor;
            const server = editorLike.get(config.mcp.server);
            if (typeof server?.url === "string")
                mcpUrl = server.url;
            mcpInfo = applyTarget(editorLike, config.mcp, { target, connectionName: pegaConnection });
        }));
        /** Config pins the folder; otherwise the user's saved choice; never an implicit default. */
        function output() {
            const suggested = suggestOutputFolder(directory) ?? null;
            if (config.fetch.outputRoot)
                return { path: config.fetch.outputRoot, source: "config", suggested };
            if (savedOutput)
                return { path: savedOutput, source: "saved", suggested };
            return { path: null, source: "none", suggested };
        }
        /** Core is always loopback: explicit option, else the MCP server's origin, else the VSIX default. */
        function service() {
            return config.core.baseUrl ?? coreServiceBaseUrl(mcpUrl) ?? DEFAULTS.coreBaseUrl;
        }
        async function liveTargets() {
            const { token } = await currentToken();
            if (!token)
                return { status: "missing" };
            return portal.fetchTargets(token);
        }
        let emitTarget;
        function emitEvent(name, data) {
            emitTarget?.(name, data);
        }
        async function requireSession(context) {
            const { token } = await currentToken();
            if (!token)
                throw context.error("not_signed_in", "Sign in to Prodigo first (/prodigo → Sign in).", {});
            if (!target)
                throw context.error("no_target", "Select a Pega target first (/prodigo → Select Pega target).", {});
            return { token, target };
        }
        async function requireConnection(context) {
            const session = await requireSession(context);
            if (!pegaConnection) {
                throw context.error("no_connection", "Connect a Pega operator for this target first (/prodigo → Connect Pega operator).", {});
            }
            return { ...session, connection: pegaConnection };
        }
        function coreFailure(context, error) {
            if (error instanceof CoreTrustError) {
                if (error.code === "CORE_UNREACHABLE") {
                    throw context.error("network", `${error.message}. Is the Prodigo Core service running at ${service()}?`, { message: error.message });
                }
                throw context.error("core_error", error.message, { code: error.code, hint: error.hint ?? null });
            }
            if (error instanceof CoreError)
                throw context.error("core_error", error.message, { code: error.code, hint: error.hint ?? null });
            const message = error instanceof Error ? error.message : String(error);
            throw context.error("network", `Core service at ${service()} is unreachable: ${message}`, { message });
        }
        async function saveConnection(name, targetBaseUrl, operator, ready) {
            pegaConnection = ready ? name : undefined;
            await updateState((state) => ({
                ...state,
                pega: { connectionName: name, targetBaseUrl, username: operator, ready, updatedAt: new Date().toISOString() },
            }));
            await ctx.mcp.reload().catch(() => undefined);
            emitEvent("pega-connected", { connectionName: name, targetBaseUrl, ready });
        }
        /** Shared ending of use/login/trust: ready, trust pending, or rejected. */
        async function finishConnect(context, name, operator, setup, selected) {
            if (setup.ready) {
                await saveConnection(name, selected.baseUrl, operator, true);
                return { connectionName: name, pegaOperator: operator || null, ready: true };
            }
            if (setup.nextAction === "INITIALIZE_PEGA_TRUST") {
                await saveConnection(name, selected.baseUrl, operator, false);
                throw context.error("trust_required", "One-time Prodigo trust setup is required for this target.", {
                    connectionName: name,
                    environment: setup.target?.environment ?? null,
                    customerId: setup.target?.customerId ?? null,
                });
            }
            throw context.error("core_error", "The Core service did not accept the Pega connection.", { code: setup.nextAction ?? "PEGA_SETUP_REQUIRED", hint: null });
        }
        function connectionNameFor(targetBaseUrl, username) {
            return `OpenCode-${createHash("sha256").update(`${config.portal.baseUrl}|${targetBaseUrl.toLowerCase()}|${username}`).digest("hex").slice(0, 24)}`;
        }
        const rpcRegistration = await ctx.rpc.register(ProdigoRpc, {
            status: async () => {
                const { token, source } = await currentToken();
                const state = await readState();
                const user = state.user ?? undefined;
                return {
                    signedIn: token !== undefined,
                    tokenSource: source,
                    issuer: state.issuer ?? config.portal.baseUrl,
                    user: user ? { name: user.name ?? null, email: user.email ?? null, userType: user.userType ?? null } : null,
                    target: target ? { label: target.label, baseUrl: target.baseUrl, env: target.env ?? null } : null,
                    mcp: {
                        server: config.mcp.server,
                        header: config.mcp.header,
                        configured: mcpInfo.configured,
                        patched: mcpInfo.patched,
                    },
                    pega: state.pega
                        ? { connectionName: state.pega.connectionName, username: state.pega.username, targetBaseUrl: state.pega.targetBaseUrl, ready: state.pega.ready === true }
                        : null,
                    service: service(),
                    fetch: activeRun ? { runId: activeRun.runId, appName: activeRun.appName, message: activeRun.message } : null,
                    output: output(),
                    fetchModes: state.fetchModes ?? null,
                };
            },
            signin: async (input, context) => {
                const token = input.token;
                const validation = await portal.validateToken(token);
                if (validation.status === "invalid") {
                    throw context.error("invalid_token", validation.message ?? validation.code ?? "The Portal rejected this token.", {
                        code: validation.code ?? null,
                        message: validation.message ?? null,
                    });
                }
                if (validation.status === "error") {
                    throw context.error("network", "The Prodigo Portal could not be reached.", { message: "validation failed" });
                }
                await store
                    .write("credentials", { token, issuer: config.portal.baseUrl, updatedAt: new Date().toISOString() })
                    .catch(() => undefined);
                await updateState((state) => ({ ...state, issuer: config.portal.baseUrl, user: validation.user ?? null }));
                if (target)
                    await ctx.mcp.reload().catch(() => undefined);
                const bootstrap = await portal.fetchTargets(token);
                const count = bootstrap.status === "ok" ? bootstrap.targets.length : 0;
                return { name: validation.user?.name ?? null, email: validation.user?.email ?? null, targets: count };
            },
            signout: async () => {
                activeRun?.controller.abort();
                await store.remove("credentials").catch(() => undefined);
                await updateState(() => ({}));
                await store.remove("state").catch(() => undefined);
                target = undefined;
                pegaConnection = undefined;
                await ctx.mcp.reload().catch(() => undefined);
                emitEvent("session-cleared", {});
                return { cleared: true };
            },
            targets: async (_input, context) => {
                const result = await liveTargets();
                if (result.status === "missing")
                    throw context.error("not_signed_in", "Sign in to Prodigo first.", {});
                if (result.status === "expired")
                    throw context.error("session_expired", "The Prodigo session expired; sign in again.", {});
                if (result.status === "error")
                    throw context.error("network", result.message, { message: result.message });
                return {
                    targets: result.targets.map((entry) => ({
                        label: entry.label,
                        baseUrl: entry.baseUrl,
                        env: entry.env ?? null,
                        restriction: entry.restriction ? { status: entry.restriction.status, reason: entry.restriction.reason ?? null } : null,
                    })),
                };
            },
            "target.select": async (input, context) => {
                const requested = String(input.baseUrl).trim().replace(/\/+$/, "");
                const result = await liveTargets();
                if (result.status === "missing")
                    throw context.error("not_signed_in", "Sign in to Prodigo first.", {});
                if (result.status === "expired")
                    throw context.error("session_expired", "The Prodigo session expired; sign in again.", {});
                if (result.status === "error")
                    throw context.error("network", result.message, { message: result.message });
                const choice = result.targets.find((entry) => entry.baseUrl.toLowerCase() === requested.toLowerCase());
                if (!choice)
                    throw context.error("not_found", "That URL is not an approved target.", { baseUrl: requested });
                if (choice.restriction?.status === "blocked") {
                    throw context.error("blocked", choice.restriction.reason ?? "This target is blocked.", { reason: choice.restriction.reason ?? null });
                }
                const switched = !target || target.baseUrl.toLowerCase() !== choice.baseUrl.toLowerCase();
                target = { baseUrl: choice.baseUrl, label: choice.label, env: choice.env ?? null, updatedAt: new Date().toISOString() };
                const selected = target;
                if (switched)
                    pegaConnection = undefined;
                await updateState((state) => {
                    const { pega, ...rest } = state;
                    return switched ? { ...rest, target: selected } : { ...rest, ...(pega ? { pega } : {}), target: selected };
                });
                await ctx.mcp.reload().catch(() => undefined);
                emitEvent("target-updated", { label: choice.label, baseUrl: choice.baseUrl });
                return {
                    label: choice.label,
                    baseUrl: choice.baseUrl,
                    env: choice.env ?? null,
                    mcpConfigured: mcpInfo.configured,
                    connectionKept: !switched && pegaConnection !== undefined,
                };
            },
            "target.clear": async () => {
                target = undefined;
                pegaConnection = undefined;
                await updateState((state) => {
                    const { target: _gone, pega: _p, ...rest } = state;
                    return rest;
                });
                await ctx.mcp.reload().catch(() => undefined);
                return { cleared: true };
            },
            "pega.connections": async (_input, context) => {
                const { token, target: selected } = await requireSession(context);
                try {
                    const rows = await trust.list({ baseUrl: service(), token });
                    return {
                        connections: rows
                            .filter((row) => sameTarget(selected.baseUrl, row.targetBaseUrl))
                            .map((row) => ({ name: row.name, pegaOperator: row.pegaOperator, selected: row.name === pegaConnection })),
                    };
                }
                catch (error) {
                    return coreFailure(context, error);
                }
            },
            "pega.use": async (input, context) => {
                const { token, target: selected } = await requireSession(context);
                let setup;
                let operator = "";
                try {
                    // Only a connection the caller owns for this target can be selected.
                    const owned = (await trust.list({ baseUrl: service(), token })).find((row) => row.name === input.name && sameTarget(selected.baseUrl, row.targetBaseUrl));
                    if (!owned)
                        throw new CoreTrustError("That connection is not enrolled for the selected target under your Prodigo identity.", "CONNECTION_NOT_OWNED");
                    operator = owned.pegaOperator ?? "";
                    setup = await trust.connect({ baseUrl: service(), token, name: input.name });
                }
                catch (error) {
                    return coreFailure(context, error);
                }
                return finishConnect(context, input.name, operator, setup, selected);
            },
            "pega.login": async (input, context) => {
                const { token, target: selected } = await requireSession(context);
                const username = input.username.trim();
                const name = connectionNameFor(selected.baseUrl, username);
                let setup;
                try {
                    setup = await trust.enroll({ baseUrl: service(), token, name, targetBaseUrl: selected.baseUrl, username, password: input.password });
                }
                catch (error) {
                    return coreFailure(context, error);
                }
                return finishConnect(context, name, username, setup, selected);
            },
            "pega.trust": async (_input, context) => {
                const { token, target: selected } = await requireSession(context);
                const state = await readState();
                const pending = state.pega && sameTarget(selected.baseUrl, state.pega.targetBaseUrl) ? state.pega : undefined;
                if (!pending)
                    throw context.error("no_connection", "No Pega connection is enrolled for this target yet.", {});
                let setup;
                try {
                    setup = await trust.initialize({ baseUrl: service(), token, name: pending.connectionName });
                }
                catch (error) {
                    return coreFailure(context, error);
                }
                return finishConnect(context, pending.connectionName, pending.username, setup, selected);
            },
            "rules.apps": async (_input, context) => {
                const { token, connection } = await requireConnection(context);
                try {
                    return { apps: await core.applications({ service: service(), token, connection }) };
                }
                catch (error) {
                    return coreFailure(context, error);
                }
            },
            "rules.rulesets": async (input, context) => {
                const { token, connection } = await requireConnection(context);
                try {
                    return { rulesets: await core.rulesets({ service: service(), token, connection, ...input }) };
                }
                catch (error) {
                    return coreFailure(context, error);
                }
            },
            "rules.fetch": async (input, context) => {
                const { token, connection } = await requireConnection(context);
                if (activeRun)
                    throw context.error("busy", `A fetch is already running (${activeRun.appName}).`, { runId: activeRun.runId });
                const folder = output();
                if (!folder.path) {
                    throw context.error("no_output_folder", "Choose where fetched rules are saved first (/prodigo → Set rules folder).", { suggested: folder.suggested });
                }
                const outputRoot = folder.path;
                const coreUrl = service();
                let runId;
                try {
                    ;
                    ({ runId } = await core.startFetch({
                        service: coreUrl,
                        token,
                        connection,
                        runId: randomUUID(),
                        applicationId: input.applicationId,
                        rulesets: input.rulesetIds,
                        ruleTypes: ALL_RULE_TYPE_IDS,
                        outputRoot,
                        onConflict: input.onConflict,
                    }));
                }
                catch (error) {
                    return coreFailure(context, error);
                }
                await updateState((state) => ({ ...state, fetchModes: { ...(state.fetchModes ?? {}), [input.applicationId]: input.onConflict } }));
                const run = { runId, appName: input.appName, controller: new AbortController(), message: null };
                activeRun = run;
                const base = { runId, appName: input.appName };
                emitEvent("rules-progress", { ...base, phase: "start", message: "Fetch accepted by Core" });
                void core
                    .observe({
                    service: coreUrl,
                    token,
                    connection,
                    runId,
                    signal: run.controller.signal,
                    onEvent: (event) => {
                        if (event.step === "done" || event.step === "error")
                            return;
                        const message = describeRunEvent(event);
                        if (!message)
                            return;
                        run.message = message;
                        emitEvent("rules-progress", { ...base, phase: "progress", message });
                    },
                })
                    .then((result) => {
                    if (result.status === "done") {
                        emitEvent("rules-progress", {
                            ...base,
                            phase: "done",
                            message: "Fetch complete",
                            outputRoot: result.summary.outputRoot ?? outputRoot,
                            rules: result.summary.counts.rules,
                            rulesets: result.summary.rulesets.length,
                            missing: result.summary.missingRulesets.length,
                        });
                    }
                    else if (result.status === "error") {
                        emitEvent("rules-progress", { ...base, phase: "failed", code: result.code, message: result.hint });
                    }
                    else {
                        emitEvent("rules-progress", { ...base, phase: "detached", message: "Stopped following the fetch; Core continues it in the background." });
                    }
                })
                    .catch((error) => {
                    emitEvent("rules-progress", { ...base, phase: "failed", code: "OBSERVER_FAILED", message: error instanceof Error ? error.message : String(error) });
                })
                    .finally(() => {
                    if (activeRun === run)
                        activeRun = undefined;
                });
                return { runId, outputRoot };
            },
            "output.set": async (input, context) => {
                let folder;
                try {
                    folder = normalizeOutputFolder(input.path);
                    await ensureWritableFolder(folder);
                }
                catch (error) {
                    const message = error instanceof OutputFolderError ? error.message : String(error);
                    throw context.error("invalid_folder", message, { message });
                }
                const settings = (await store.read("settings").catch(() => undefined)) ?? {};
                try {
                    await store.write("settings", { ...settings, outputRoot: folder });
                }
                catch (error) {
                    const message = `Could not save this choice: ${error instanceof Error ? error.message : String(error)}`;
                    throw context.error("invalid_folder", message, { message });
                }
                savedOutput = folder;
                return { path: folder, overriddenByConfig: config.fetch.outputRoot !== undefined };
            },
            "rules.detach": async () => {
                const run = activeRun;
                if (!run)
                    return { detached: false, runId: null };
                run.controller.abort();
                activeRun = undefined;
                return { detached: true, runId: run.runId };
            },
        });
        registrations.push(rpcRegistration);
        const events = rpcRegistration.events;
        if (events)
            emitTarget = (name, data) => void events.emit?.(name, data).catch(() => undefined);
        return async () => {
            activeRun?.controller.abort();
            emitTarget = undefined;
            await Promise.allSettled(registrations.map((registration) => registration.dispose()));
        };
    },
});
